package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string
	ScPrin  decimal.Decimal
	ScRate  decimal.Decimal
	ScYears int64
}

var WsEofFlag string = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsYear int64 = 0
var WsCount int64 = 0
var WsBalEd string = ""

var schedRec SchedRec

var schedFile *os.File
var scanner *bufio.Scanner
var atEOF bool = false

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func padRight(s string, n int) string {
	if len(s) >= n {
		if len(s) > n {
			return s[:n]
		}
		return s
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseIntField(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	// fields are digits only; allow sign
	var v int64
	fmt.Sscan(t, &v)
	// fallback manual parse
	// fmt.Sscan handles correctly; if failed try ParseInt
	return v
}

func storeWsBal(d decimal.Decimal) decimal.Decimal {
	// d is already rounded to 2 decimals
	// apply overflow: keep low-order 10 scaled digits (8 integer +2 decimal)
	// modulus = 10^10
	scaled := d.Shift(2) // *100
	// truncate toward zero to integer (should already be integer)
	scaled = scaled.Truncate(0)
	iv := scaled.IntPart()
	mod := int64(10000000000) // 1e10
	// Go mod keeps sign of dividend, which matches COBOL high-order drop keeping sign
	low := iv % mod
	// decimal.New with scale -2
	return decimal.New(low, -2)
}

func formatWsBalEd(v decimal.Decimal) string {
	// v is already stored (scale 2, within capacity)
	// Build formatted string for PIC ZZ,ZZZ,ZZ9.99  (13 chars)
	// nInt =8, nFrac=2
	scaled := v.Shift(2).Truncate(0).IntPart()
	// preserve sign? assume positive; handle negative by sign
	negative := scaled < 0
	if negative {
		scaled = -scaled
	}
	intPart := scaled / 100
	fracPart := scaled % 100

	// integer digits zero-padded to 8
	intDigits := fmt.Sprintf("%08d", intPart) // 8 chars '0'..'9'
	// Build integer edited with commas: pattern ZZ,ZZZ,ZZ9 -> commas after 2 and after 5
	// positions for digits: D0 D1 , D2 D3 D4 , D5 D6 D7  => total 10 chars
	var intWithCommas [10]byte
	// fill
	intWithCommas[0] = intDigits[0]
	intWithCommas[1] = intDigits[1]
	intWithCommas[2] = ','
	intWithCommas[3] = intDigits[2]
	intWithCommas[4] = intDigits[3]
	intWithCommas[5] = intDigits[4]
	intWithCommas[6] = ','
	intWithCommas[7] = intDigits[5]
	intWithCommas[8] = intDigits[6]
	intWithCommas[9] = intDigits[7]

	// Z suppression
	// Determine string array to mutate
	outInt := make([]byte, 10)
	copy(outInt, intWithCommas[:])
	suppressed := true
	// Need to know if digit is '0' and we are still suppressed
	// We walk left to right over outInt
	// When we encounter a digit, if suppressed && digit=='0' and not the last digit position, blank it
	// When we encounter ',', if suppressed, blank it
	// Last digit position is index 9 (the '9' in picture) – never suppressed
	for i := 0; i < len(outInt); i++ {
		c := outInt[i]
		if c == ',' {
			if suppressed {
				outInt[i] = ' '
			}
		} else { // digit
			isLast := i == len(outInt)-1
			if suppressed && c == '0' && !isLast {
				outInt[i] = ' '
			} else {
				// first non-zero or last
				suppressed = false
				// keep digit
			}
		}
	}

	fracStr := fmt.Sprintf("%02d", fracPart)
	result := string(outInt) + "." + fracStr
	if negative {
		// Put minus in leftmost space if possible; simple: replace first space with '-'
		// COBOL would have sign handling; not needed for tests
		b := []byte(result)
		for i := 0; i < len(b); i++ {
			if b[i] == ' ' {
				b[i] = '-'
				break
			}
			if b[i] != ' ' && b[i] != ',' && b[i] != '.' {
				// no space, overwrites?
				break
			}
		}
		result = string(b)
	}
	return result
}

func MAIN_PARA() {
	var err error
	schedFile, err = os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty
		WsEofFlag = "Y"
		atEOF = true
	} else {
		defer schedFile.Close()
		scanner = bufio.NewScanner(schedFile)
		READ_PARA()
		for !isInputDone() {
			PROCESS_PARA()
		}
		// close already deferred
	}
	// DISPLAY "SCHEDULES: " WS-COUNT
	// unedited numeric: zero-padded width 2
	fmt.Printf("SCHEDULES: %02d\n", WsCount)
}

func READ_PARA() {
	if atEOF {
		WsEofFlag = "Y"
		return
	}
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if !scanner.Scan() {
		WsEofFlag = "Y"
		atEOF = true
		return
	}
	line := scanner.Text()
	// remove possible \r
	if strings.HasSuffix(line, "\r") {
		line = strings.TrimSuffix(line, "\r")
	}
	// pad to 16 with spaces if shorter
	if len(line) < 16 {
		line = padRight(line, 16)
	}
	if len(line) > 16 {
		line = line[:16]
	}
	// parse
	schedRec.ScAcct = line[0:4]
	prinStr := line[4:11]
	rateStr := line[11:15]
	yearsStr := line[15:16]

	pv := parseIntField(prinStr)
	rv := parseIntField(rateStr)
	yv := parseIntField(yearsStr)

	schedRec.ScPrin = decimal.New(pv, -2)
	schedRec.ScRate = decimal.New(rv, -2)
	schedRec.ScYears = yv
}

func PROCESS_PARA() {
	// MOVE SC-PRIN TO WS-BAL
	WsBal = schedRec.ScPrin
	// PERFORM VARYING WS-YEAR FROM 1 BY 1 UNTIL WS-YEAR > SC-YEARS
	for WsYear = 1; WsYear <= schedRec.ScYears; WsYear++ {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		rateDiv := schedRec.ScRate.Shift(-2) // /100
		one := decimal.NewFromInt(1)
		factor := one.Add(rateDiv)
		raw := WsBal.Mul(factor)
		rounded := raw.Round(2) // half away from zero for positive
		WsBal = storeWsBal(rounded)
		WsBalEd = formatWsBalEd(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		// WS-YEAR is PIC 99 zero-padded
		fmt.Printf("%s Y%02d %s\n", schedRec.ScAcct, WsYear, WsBalEd)
	}
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", schedRec.ScAcct, WsBalEd)
	WsCount++
	READ_PARA()
}

func main() {
	MAIN_PARA()
}

